import { describe, it, expect } from 'vitest';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { repoRoot } from '../../test/files';

/**
 * These are the authorization invariants for the platform.
 *
 * `pocketbase/schema/effective-rules.json` is generated by `npm run schema:rules`, which
 * applies every migration to a throwaway database with the real PocketBase binary and dumps
 * the resulting rules. CI regenerates it and fails if it drifts, so this file asserts against
 * what PocketBase actually computes rather than what the migration source appears to say.
 *
 * `null` means superuser-only. `''` means completely open, including unauthenticated.
 */

type Collection = {
  rules: {
    listRule: string | null;
    viewRule: string | null;
    createRule: string | null;
    updateRule: string | null;
    deleteRule: string | null;
  };
  fields: { name: string; type: string; required: boolean }[];
};

const schema: Record<string, Collection> = JSON.parse(
  readFileSync(join(repoRoot, 'pocketbase/schema/effective-rules.json'), 'utf8')
);

const rules = Object.fromEntries(
  Object.entries(schema).map(([name, collection]) => [name, collection.rules])
);

/** Collections whose rows are private to specific users. */
const PRIVATE_COLLECTIONS = [
  'messages',
  'trades',
  'notifications',
  'watchlist',
  'verification_requests',
  'verification_links',
  'verifier_settings',
];

/** Fields a user must never be able to write on their own record. */
const PROTECTED_USER_FIELDS = [
  'trade_count',
  'vouch_count',
  'cascade_reputation',
  'cascades_seeded',
  'cascades_received',
  'cascades_passed',
  'cascades_broken',
  'phone_verified',
];

describe('collection rules', () => {
  it('covers every collection the migrations create', () => {
    expect(Object.keys(rules).length).toBeGreaterThan(20);
  });

  describe('timestamps are maintained by PocketBase', () => {
    // A required `created`/`updated` that is a plain date field must be supplied by every
    // caller or the write 400s. No client sends them, so this shape is always a broken
    // collection — it is what made every vouch creation fail.
    const manual = Object.entries(schema).flatMap(([name, collection]) =>
      collection.fields
        .filter((f) => ['created', 'updated'].includes(f.name))
        .filter((f) => f.required && f.type !== 'autodate')
        .map((f) => `${name}.${f.name}`)
    );

    it('has no required manually-supplied timestamps', () => {
      expect(manual).toEqual([]);
    });
  });

  describe('counters and flags are not required', () => {
    // PocketBase treats 0 and false as blank, so a required number or bool field rejects
    // its own natural initial value. `listings.views`, `notifications.read` and friends
    // made listing creation and every notification write fail.
    const required = Object.entries(schema).flatMap(([name, collection]) =>
      collection.fields
        .filter((f) => f.required && ['number', 'bool'].includes(f.type))
        .map((f) => `${name}.${f.name}`)
    );

    it('has no required number or bool fields', () => {
      expect(required).toEqual([]);
    });
  });

  describe('private data is never world-readable', () => {
    it.each(PRIVATE_COLLECTIONS)('%s is not publicly listable or viewable', (name) => {
      expect(rules[name]).toBeDefined();
      expect(rules[name].listRule).not.toBe('');
      expect(rules[name].viewRule).not.toBe('');
    });
  });

  describe('nothing is writable by anonymous callers', () => {
    const writable = Object.entries(rules).flatMap(([name, r]) =>
      (['createRule', 'updateRule', 'deleteRule'] as const)
        .filter((key) => r[key] === '')
        // Registration is the one legitimate anonymous write.
        .filter((key) => !(name === 'users' && key === 'createRule'))
        .map((key) => `${name}.${key}`)
    );

    it('has no open create/update/delete rules', () => {
      expect(writable).toEqual([]);
    });
  });

  describe('users cannot award themselves reputation', () => {
    it.each(PROTECTED_USER_FIELDS)('users.updateRule rejects writes to %s', (field) => {
      expect(rules.users.updateRule).toContain(`@request.body.${field}:isset = false`);
    });

    // Registration is anonymous, so without this a new account can be created with any
    // starting reputation it likes.
    it.each(PROTECTED_USER_FIELDS)('users.createRule rejects writes to %s', (field) => {
      expect(rules.users.createRule).toContain(`@request.body.${field}:isset = false`);
    });
  });

  describe('trades cannot be forged', () => {
    it('requires the creator to be the buyer', () => {
      expect(rules.trades.createRule).toContain('@request.body.buyer = @request.auth.id');
    });

    it('forbids trading with yourself', () => {
      expect(rules.trades.createRule).toContain('@request.body.seller != @request.auth.id');
    });
  });

  describe('vouches cannot be forged', () => {
    it('requires the creator to be the voucher', () => {
      expect(rules.vouches.createRule).toContain('@request.body.voucher = @request.auth.id');
    });

    it('forbids vouching for yourself', () => {
      expect(rules.vouches.createRule).toContain('@request.body.vouchee != @request.auth.id');
    });
  });

  describe('notifications cannot be used to impersonate the platform', () => {
    it('is not creatable anonymously', () => {
      expect(rules.notifications.createRule).not.toBe('');
    });

    // Superuser-only creation silently 403s all 18 client call sites. Authenticated
    // creation is allowed, with the dangerous fields constrained by pb_hooks.
    it('is creatable by authenticated users', () => {
      expect(rules.notifications.createRule).not.toBeNull();
      expect(rules.notifications.createRule).toContain('@request.auth.id');
    });

    it('is only readable by its recipient', () => {
      expect(rules.notifications.listRule).toBe('user = @request.auth.id');
      expect(rules.notifications.viewRule).toBe('user = @request.auth.id');
    });
  });

  describe('no collection is writable but unreadable', () => {
    // A collection regular users can write but only superusers can read is always a bug:
    // the feature that writes it can never read its own data back.
    const broken = Object.entries(rules)
      .filter(([, r]) => r.createRule !== null && r.listRule === null && r.viewRule === null)
      .map(([name]) => name);

    it('has no create-allowed / read-denied collections', () => {
      expect(broken).toEqual([]);
    });
  });
});
